import{z as i,x as s,o as t,c as d,q as A,j as o,D as e,d as B,s as r,S as l,b as a}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"地理空间的深化","description":"","frontmatter":{"title":"地理空间的深化","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/alt-geo-deep.md","filePath":"quant/alt-geo-deep.md","lastUpdated":1791413859000}'),p={name:"quant/alt-geo-deep.md"};function u(m,E,C,D,F,f){const n=s("Mermaid");return t(),d("div",null,[E[2]||(E[2]=A('<h1 id="地理空间的深化" tabindex="-1">地理空间的深化 <a class="header-anchor" href="#地理空间的深化" aria-label="Permalink to &quot;地理空间的深化&quot;">​</a></h1><div class="epigraph"><p>传感器看到的是地块，组合需要的是公司；地理数据深化的主要误差发生在那一次映射里，而不是卫星里。</p><footer>—— 据 Donaldson and Storeygard, Journal of Economic Perspectives, 2016；Addoum, Ng and Ortiz-Bobea, Review of Financial Studies, 2020 整理</footer></div><p><a href="/quant/alt-supply-graph">上一课</a>把文本与披露拼成供应链图谱，冲击传导有了带时间戳的边。本课把同样的对齐问题搬到空间上。主干课的<a href="/quant/satellite-geo">卫星与地理</a>立了夜灯与经济活动的关系、传感器换代与云层的坑；<a href="/quant/satellite-to-feature">卫星到特征</a>立了节点存档、云掩膜与传感器交叉校准的管道纪律。本课的深化在<strong>特征之后</strong>：地块数字怎么变成公司面板，空间结构怎么改变检验，以及手机面板这类新传感怎么合规地进来。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>缺口在「传感器到特征」与「特征到公司」之间。三个坑。映射错：兴趣区圈错地块，或门店、厂房、仓库归属错公司——用总部坐标当经营位置是最常见的错法，总部在纽约的零售商，其营收不发生在纽约。加总任意：同一批地块换一种分格加总，结论可以翻转，这是可修改面积单元问题的老病（Openshaw, 1984）。推断失效：地理相邻的观测误差相关，普通标准误把 \\(t\\) 值抬高数倍，虚假显著在空间数据里是常态而不是例外。不解决这三件事，把县夜灯乘一个权重就当公司营收 nowcast，得到的不是信号而是加了噪声的行业暴露。</p><p><span class="marginnote">AOI（Area of Interest，兴趣区）就是你在地图上圈出来的那块地：一家门店的停车场、一个厂房的屋顶。圈大圈小直接影响读数——圈进马路会把过路车算成顾客车，圈掉半个停车场又会漏数。所以 AOI 要当数据库管理，带版本与变更记录，而不是随手画个圈。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对齐管线四步。其一，兴趣区库版本化：门店、厂房、物流设施的多边形各自成表，关联到证券，关联切换走<a href="/quant/corporate-action-engine">公司行动</a>的有效日——并购与关店改映射，不改历史。其二，加总规则显式声明：聚合频率、缺失阈值、重访不均的加权方式，重访周期不规则的传感器按观测时间加权而不是按日历等权。其三，检验按空间做：按地区聚类或方块自助，验证集按地理留出——训练北美、验证欧洲，防止空间泄漏让回测好看。其四，增量相对基准：对官方统计与分部披露的增量定义信息（<a href="/quant/segment-geo">分部披露的地区口径</a>另有其坑）。新传感两条：高分辨率设施观测与手机位置面板，后者必须在聚合层以上停留，最小化与删除义务沿用<a href="/quant/web-data-compliance">网络数据合规</a>的口径。</p><p><span class="marginnote">为什么空间相关能把 t 值抬高数倍：相邻地块共享同一片天气、同一个商圈，误差像互相抄作业一样彼此相似。名义上有 500 个观测，有效样本可能只有 50 个——不校正标准误，一个纯属巧合的「显著」关系就能轻松混过 t=2 的门槛。</span></p>',9)),(t(),o(l,null,{default:e(()=>[r(n,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E4%BC%A0%E6%84%9F%E5%99%A8%E8%A7%82%E6%B5%8B%EF%BC%9A%E5%BD%B1%E5%83%8F%E3%80%81%E7%81%AF%E3%80%81%E8%88%B9%E4%BD%8D%E3%80%81%E4%BD%8D%E7%BD%AE%E9%9D%A2%E6%9D%BF%22%5D%20--%3E%20A%5B%22AOI%20%E5%BA%93%EF%BC%9A%E7%89%88%E6%9C%AC%E5%8C%96%E5%A4%9A%E8%BE%B9%E5%BD%A2%22%5D%0A%20%20A%20--%3E%20M%5B%22%E5%AE%9E%E4%BD%93%E6%98%A0%E5%B0%84%EF%BC%9A%E5%9C%B0%E5%9D%97%E5%88%B0%E8%AF%81%E5%88%B8%EF%BC%8C%E8%B5%B0%E5%85%AC%E5%8F%B8%E8%A1%8C%E5%8A%A8%E6%97%A5%22%5D%0A%20%20M%20--%3E%20P%5B%22%E7%A9%BA%E9%97%B4%E5%8A%A0%E6%80%BB%EF%BC%9A%E9%A2%91%E7%8E%87%E3%80%81%E7%BC%BA%E5%A4%B1%E3%80%81%E9%87%8D%E8%AE%BF%E5%8A%A0%E6%9D%83%22%5D%0A%20%20P%20--%3E%20T%5B%22%E7%A9%BA%E9%97%B4%E6%8E%A8%E6%96%AD%EF%BC%9A%E5%9C%B0%E5%8C%BA%E8%81%9A%E7%B1%BB%E4%B8%8E%E5%9C%B0%E7%90%86%E7%95%99%E5%87%BA%22%5D%0A%20%20T%20--%3E%20F%5B%22%E5%85%AC%E5%8F%B8%E7%BA%A7%E7%89%B9%E5%BE%81%E4%B8%8E%E5%A2%9E%E9%87%8F%E6%A3%80%E9%AA%8C%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[B("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,"映射为什么是主要误差源：传感器误差主干课讲过（云、饱和、换代），这里难的是公司层。停车场车辆数到收入的弹性随业态变化——折扣店与奢侈品店的转化率不同，同一个车流数含义不同；地理暴露到定价的通道则是另一条线：气候新闻可以对冲（Engle, Giglio, Kelly, Lee and Stroebel, 2020），海平面上升已进入沿海房价（Bernstein, Gustafson and Lewis, 2019），干旱暴露压 agricultural 收益（Hong, Li and Xu, 2019），公司地址与设施位置决定谁暴露多少——Addoum, Ng and Ortiz-Bobea（2020）正是把温度冲击对齐到设施位置才做出识别。不按管线走的错法：用住宅区夜灯外推工业用电，把城市化当成了产出。",-1)),E[5]||(E[5]=a("p",null,[a("span",{class:"marginnote"},"DMSP-OLS 夜灯只有 6 比特量化，取值 0 到 63，明亮城市核早早饱和，增长读不出来；VIIRS 自 2012 年起以辐射校准接替（Donaldson–Storeygard, 2016 对此有专节）。做十年以上的夜灯面板，先写世代拼接规则，再谈 IC。")],-1)),E[6]||(E[6]=a("p",null,"可修改面积单元问题（MAUP）为什么能翻转结论——回答「同一批地块换种分法怎么就变了答案」：",-1)),(t(),o(l,null,{default:e(()=>[r(n,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20G%5B%22%E5%90%8C%E4%B8%80%E6%89%B9%E5%9C%B0%E5%9D%97%E8%A7%82%E6%B5%8B%22%5D%20--%3E%20Z1%5B%22%E5%88%86%E6%A0%BC%20A%EF%BC%9A%E6%8C%89%E5%8E%BF%E7%95%8C%E5%8A%A0%E6%80%BB%22%5D%0A%20%20G%20--%3E%20Z2%5B%22%E5%88%86%E6%A0%BC%20B%EF%BC%9A%E6%8C%89%E5%95%86%E5%9C%88%E5%8A%A0%E6%80%BB%22%5D%0A%20%20Z1%20--%3E%20R1%5B%22%E8%AF%BB%E6%95%B0%E4%B8%80%EF%BC%9A%E6%A0%B8%E5%BF%83%E5%9F%8E%E5%8C%BA%E8%B4%A1%E7%8C%AE%E4%B8%BB%E8%A6%81%E5%A2%9E%E9%95%BF%22%5D%0A%20%20Z2%20--%3E%20R2%5B%22%E8%AF%BB%E6%95%B0%E4%BA%8C%EF%BC%9A%E8%BF%91%E9%83%8A%E9%97%A8%E5%BA%97%E8%B4%A1%E7%8C%AE%E4%B8%BB%E8%A6%81%E5%A2%9E%E9%95%BF%22%5D%0A%20%20R1%20--%3E%20X%5B%22%E6%95%B0%E6%8D%AE%E6%B2%A1%E5%8F%98%EF%BC%8C%E7%AD%94%E6%A1%88%E5%8F%98%E4%BA%86%EF%BC%9A%E5%8A%A0%E6%80%BB%E8%A7%84%E5%88%99%E5%BF%85%E9%A1%BB%E5%85%88%E5%A3%B0%E6%98%8E%22%5D%0A%20%20R2%20--%3E%20X%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[7]||(E[7]=A('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>夜灯宏观测量与云掩膜管道是主干课与特征课的对象，不重讲；农业天气溢价的交易化另有其课（<a href="/quant/ag-weather-premium">农业天气溢价</a>）。手机面板不落个人级数据，轨迹再识别风险使聚合门槛不可放松。空间相关校正改变的是标准误不是系数：校正之后仍在的效应才值得进因子库。地理数据的覆盖率随公司业态分化，覆盖阈值决定谁进当日截面，这一横截面纪律归面板构造主干课管辖。</p><p><span class="marginnote">初学者容易把「聚类标准误」当成让结果变显著的工具。方向通常相反：校正后有效样本变少，t 值往往下降、显著性消失——留下来的才是真效应。就像换了严监考后分数普遍下降，还剩下的高分才可信。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>深化发生在特征之后：兴趣区版本化、实体映射、加总规则、空间推断四步缺一不可。</li><li>总部坐标不是经营位置；映射误差是公司级地理信号的主要误差源。</li><li>空间相关使常规标准误失效，按地区聚类与地理留出是回测的最低配置。</li><li>世代拼接（如 DMSP 到 VIIRS）先于任何十年期夜灯面板。</li><li>出处：Donaldson and Storeygard, <em>JEP</em>, 2016；Addoum, Ng and Ortiz-Bobea, <em>RFS</em>, 2020；Engle, Giglio, Kelly, Lee and Stroebel, <em>RFS</em>, 2020；Bernstein, Gustafson and Lewis, <em>JFE</em>, 2019；Hong, Li and Xu, <em>JFE</em>, 2019；Openshaw, 1984。</li></ul>',5))])}const c=i(p,[["render",u]]);export{h as __pageData,c as default};
